SourceCode.Declaration:
internal final class TAMRebateDealDeactivateGUP
{
    protected TAMRebateDealRecId dealRecId;

}

Method.Source:
internal void run()
{
    #OCCRetryCount

    setPrefix("@RebatesAndDeductions:DeactivateRebateAgreement");

    if (!this.validateDeactivate())
    {
        throw error("@SYS18447");
    }

    try
    {
        this.deactivateRebateDeal();

        info("@RebatesAndDeductions:DeactivateRebateAgreementSuccessfully");
    }
    #StandardRetryCatchBlock
}

private boolean validateDeactivate()
{
    if (!TAMRebateDeal::find(dealRecId).RebateActive)
    {
        return checkFailed("@RebatesAndDeductions:RebateDeactivateFailedDueToInactiveAgreement");
    }

    return true;
}

private void deactivateRebateDeal()
{
    TAMRebateDeal rebateDeal = TAMRebateDeal::find(dealRecId, true);

    if (rebateDeal)
    {
        ttsbegin;

        rebateDeal.RebateActive = NoYes::No;
        rebateDeal.State = TAMRebateDealWorkflowState::Draft;
        rebateDeal.update();

        ttscommit;
    }
}

internal static void main(Args _args)
{
    if (!_args.record())
    {
        return;
    }

    TAMRebateDeal rebateDeal = _args.record() as TAMRebateDeal;

    TAMRebateDealDeactivateGUP::newFromRebateDealRecId(rebateDeal.RecId).run();

    FormObjectSet formDataSource = FormDataUtil::getFormDataSource(rebateDeal);
    if (formDataSource)
    {
        formDataSource.research(true);
    }
}

internal static TAMRebateDealDeactivateGUP newFromRebateDealRecId(TAMRebateDealRecId _rebateDealRecId)
{
    if (!_rebateDealRecId)
    {
        throw error(strFmt("@SYS19306", funcName()));
    }

    TAMRebateDealDeactivateGUP rebateDealDeactivate = new TAMRebateDealDeactivateGUP();

    rebateDealDeactivate.dealRecId = _rebateDealRecId;

    return rebateDealDeactivate;
}
